'use strict';
// Coche: Porsche 911 GT3 R (Generación 992 - 2024)
// - Motor 4.2L Bóxer de 6 cilindros atmosférico con 565 CV a 9250 rpm.
// - Decoración oficial Manthey Racing "Grello" (#91 DTM / Nürburgring 24h).
// - Aerodinámica de efecto suelo con difusor bajo el morro y alerón 'cuello de cisne'.
// - Suspensión delantera de doble trapecio (heredada del 911 RSR) con una precisión quirúrgica.
// - El sonido icónico e inconfundible del Flat-6 Porsche aullando a más de 9000 rpm.
(() => {

const ATLAS_B64 = "data:image/png;base64,";
const BODY_V = "";
const BODY_I = "";
const GLASS_V = "";
const GLASS_I = "";
const WHEEL_V = "";
const WHEEL_I = "";

function b64ToF32(b64) {
  const bin = atob(b64);
  const buf = new ArrayBuffer(bin.length);
  const u8 = new Uint8Array(buf);
  for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
  return new Float32Array(buf);
}
function b64ToU32(b64) {
  const bin = atob(b64);
  const buf = new ArrayBuffer(bin.length);
  const u8 = new Uint8Array(buf);
  for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
  return new Uint32Array(buf);
}

WGSL["mat_porsche_992_gt3r"] = `// Material Porsche 992 GT3 R Manthey Grello
#include mesh_vert
@group(3) @binding(0) var tAtlas: texture_2d<f32>;

fn surf(in: V2F, ff: bool) -> Surface {
  var s = surfDefault(normalize(in.nrm));
  if (!ff) { s.normal = -s.normal; }

  let id = matId(in.mat);
  let p = in.ext.xyz;
  let uv = in.uv;

  let tx = textureSample(tAtlas, sLin, uv);

  if (id == 24u) {
    // Cubiertas transparentes de policarbonato de ópticas delanteras y traseras (deja ver reflectores 3D)
    discard;
  } else if (id == 26u) {
    // Carrocería Manthey Racing Grello (#91 DTM/N24) con laca brillante y color saturado
    let gCol = pow(tx.rgb, vec3f(0.88)) * vec3f(1.12, 1.14, 0.96);
    s.albedo = gCol;
    s.metal = 0.04;
    s.rough = 0.16;
    s.coat = 0.85;
    s.ao = smoothstep(0.05, 0.45, p.y) * 0.35 + 0.65;
  } else if (id == 52u || id == 67u || id == 59u || id == 34u || id == 57u) {
    // Cockpit GT3: fibra de carbono mate, jaula antivuelco FIA y tapicería oscura
    s.albedo = vec3f(0.045, 0.045, 0.05);
    s.metal = 0.10;
    s.rough = 0.70;
    s.coat = 0.0;
  } else if (id == 3u || id == 7u || id == 11u || id == 15u) {
    // Llantas BBS monobloque monotuerca GT3 grafito satinado
    s.albedo = vec3f(0.12, 0.12, 0.13);
    s.metal = 0.75;
    s.rough = 0.25;
    s.coat = 0.40;
  } else if (id == 41u || id == 43u || id == 44u) {
    // Pinzas de freno Brembo Porsche Motorsport rojas
    s.albedo = vec3f(0.88, 0.08, 0.08);
    s.metal = 0.50;
    s.rough = 0.20;
    s.coat = 0.80;
  } else if (id == 20u || id == 32u) {
    // Faros Porsche LED Matrix (reflectores cromados, óptica y lentes 3D)
    s.albedo = tx.rgb;
    s.metal = 0.85;
    s.rough = 0.14;
    s.coat = 0.60;
    s.emissive = 0.0;
  } else if (id == 18u) {
    // DRL diurnos 4 puntos LED Porsche
    s.albedo = tx.rgb;
    s.emissive = 0.35;
    s.rough = 0.10;
  } else if (id == 17u || id == 19u || id == 27u) {
    // Franja de luz LED trasera continua Porsche
    s.albedo = tx.rgb;
    s.emissive = 0.85;
    s.rough = 0.10;
  } else if (id == 28u) {
    // Molduras ópticas interiores y marcos
    s.albedo = tx.rgb;
    s.metal = 0.15;
    s.rough = 0.35;
  } else if (id == 30u || id == 50u || id == 53u || id == 68u || id == 69u) {
    // Fibra de carbono vista (techo, branquias capó, alerón trasero)
    s.albedo = vec3f(0.045, 0.045, 0.05);
    s.metal = 0.08;
    s.rough = 0.30;
    s.coat = 0.60;
  } else {
    s.albedo = tx.rgb;
    s.metal = 0.20;
    s.rough = 0.35;
  }

  return s;
}
`;

function loadAtlas() {
  const W = 2048, H = 2048;
  const tex = mkTex(W, H, 'rgba8unorm-srgb', TU.RT | TU.TB | TU.CD, { mipLevelCount: 7 });
  const initData = new Uint8Array(W * H * 4);
  initData.fill(220);
  G.dev.queue.writeTexture({ texture: tex }, initData, { bytesPerRow: W * 4 }, [W, H]);

  if (typeof Image !== 'undefined') {
    const img = new Image();
    img.src = ATLAS_B64;
    img.onload = () => {
      if (typeof createImageBitmap !== 'undefined') {
        createImageBitmap(img).then(bmp => {
          G.dev.queue.copyExternalImageToTexture({ source: bmp }, { texture: tex }, [W, H]);
          if (typeof genMips === 'function') genMips(tex, 'rgba8unorm-srgb');
        }).catch(() => {
          const cvs = document.createElement('canvas');
          cvs.width = W; cvs.height = H;
          const ctx2d = cvs.getContext('2d');
          ctx2d.drawImage(img, 0, 0);
          const id = ctx2d.getImageData(0, 0, W, H);
          G.dev.queue.writeTexture({ texture: tex }, id.data, { bytesPerRow: W * 4 }, [W, H]);
          if (typeof genMips === 'function') genMips(tex, 'rgba8unorm-srgb');
        });
      } else {
        const cvs = document.createElement('canvas');
        cvs.width = W; cvs.height = H;
        const ctx2d = cvs.getContext('2d');
        ctx2d.drawImage(img, 0, 0);
        const id = ctx2d.getImageData(0, 0, W, H);
        G.dev.queue.writeTexture({ texture: tex }, id.data, { bytesPerRow: W * 4 }, [W, H]);
        if (typeof genMips === 'function') genMips(tex, 'rgba8unorm-srgb');
      }
    };
  }
  return tex;
}

const CAR = {
  id: 'porsche-992-gt3-r-2024',
  name: 'Porsche 911 GT3 R (992)',
  subtitle: '2024 GT3 Spec · Manthey Grello #91 · 4.2L Flat-6 · 565 CV',
  specs: '1250 kg · 565 CV · Secuencial 6-vel · RWD · Manthey Aero',
  accent: '#f5c500',
  physics: {
    m: 1250, Izz: 1680, L: 2.507, a: 1.480, b: 1.027, tw: 1.69, h: 0.38, R: 0.340,
    mu: 1.74, B: 11.8, C: 1.54, driveF: 0.0,
    gears: [2.90, 2.10, 1.62, 1.30, 1.08, 0.90], final: 3.55, rev: 3.1, eff: 0.96,
    cdA: 0.65, crr: 0.010, brakeF: 0.58, halfW: 1.02, front: 2.45, rear: 2.50,
    clA: 0.96, aeroSplitF: 0.38,
    torqueBase: 380, torquePeak: 220, torqueDrop: 160, torquePeakStart: 0.55, torquePeakSpan: 4.5, torqueDropRpm: 8.5,
    shiftUpRpm: 8900, shiftDownRpm: 6600, revLimitRpm: 9250, maxRpm: 9400, idleRpm: 1250,
  },
  hud: { maxKmh: 330, maxRpm: 10.0, redlineRpm: 9.0 },
  wheelbase: 2.507, trackF: 1.710, trackR: 1.680, wheelR: 0.340,
  hubs: [
    [1.301, 0.360, -0.840],
    [1.301, 0.360, 0.840],
    [-1.206, 0.360, -0.840],
    [-1.206, 0.360, 0.840]
  ],
  slotBody: 0, slotWheel: [0, 0, 0, 0],
  tris: 0, _t: m4(), _t2: m4(), _t3: m4(), set: null, glass: null, atlasBG: null, fam: null,
  _z4: new Float32Array(4),
  inp: new Float64Array(2),

  build() {
    const fam = CAR.fam = mkFamily('car_porsche_992', { src: 'mat_porsche_992_gt3r', noCube: true });
    CAR.slotBody = objSlot();
    for (let i = 0; i < 4; i++) CAR.slotWheel[i] = objSlot();

    const set = CAR.set = new MeshSet(fam);
    const glass = CAR.glass = new GlassSet();

    const mb = new MeshBuilder(1 << 19);
    const gl = new MeshBuilder(1 << 15);
    const w = new MeshBuilder(1 << 15);

    const bV = b64ToF32(BODY_V), bI = b64ToU32(BODY_I);
    const gV = b64ToF32(GLASS_V), gI = b64ToU32(GLASS_I);
    const wV = b64ToF32(WHEEL_V), wI = b64ToU32(WHEEL_I);

    const nbV = bV.length / 9;
    for (let i = 0; i < nbV; i++) {
      mb.mat(bV[i*9 + 8]);
      mb.v(bV[i*9], bV[i*9+1], bV[i*9+2], bV[i*9+3], bV[i*9+4], bV[i*9+5], bV[i*9+6], bV[i*9+7]);
    }
    for (let i = 0; i < bI.length; i += 3) mb.tri(bI[i], bI[i+1], bI[i+2]);

    const ngV = gV.length / 9;
    for (let i = 0; i < ngV; i++) {
      gl.v(gV[i*9], gV[i*9+1], gV[i*9+2], gV[i*9+3], gV[i*9+4], gV[i*9+5], gV[i*9+6], gV[i*9+7]);
    }
    for (let i = 0; i < gI.length; i += 3) gl.tri(gI[i], gI[i+1], gI[i+2]);

    const nwV = wV.length / 9;
    for (let i = 0; i < nwV; i++) {
      w.mat(wV[i*9 + 8]);
      w.v(wV[i*9], wV[i*9+1], wV[i*9+2], wV[i*9+3], wV[i*9+4], wV[i*9+5], wV[i*9+6], wV[i*9+7]);
    }
    for (let i = 0; i < wI.length; i += 3) w.tri(wI[i], wI[i+1], wI[i+2]);

    CAR.tris = mb.ni / 3 + gl.ni / 3;
    set.add(mb.upload(), CAR.slotBody, 3);
    glass.add_(gl.upload(), CAR.slotBody);

    const wm = w.upload();
    CAR.tris += 4 * w.ni / 3;
    for (let i = 0; i < 4; i++) set.add(wm, CAR.slotWheel[i], 3);

    const tex = loadAtlas();
    R.drawables.push({
      draw(pass, ctx) {
        if (ctx.kind === KIND.SHADOW && ctx.cascade === 3) return;
        if (!CAR.atlasBG) {
          if (!fam.bgl3) return;
          CAR.atlasBG = G.dev.createBindGroup({ layout: fam.bgl3, entries: [{ binding: 0, resource: tex.createView() }] });
        }
        pass.setBindGroup(3, CAR.atlasBG);
        set.draw(pass, ctx);
      },
    });
    R.transparents.push(glass);

    m4ident(CAR._t);
    CAR.place(CAR._t, CAR._z4, CAR._z4);
    CAR.place(CAR._t, CAR._z4, CAR._z4);
    console.log('[Porsche 992 GT3 R] Inicializado con éxito. Triángulos:', CAR.tris);
  },

  place(body, spin, susp) {
    const steer = CAR.inp[0];
    const t = CAR._t2;
    objPrev(CAR.slotBody).set(objModel(CAR.slotBody));
    objModel(CAR.slotBody).set(body);
    for (let i = 0; i < 4; i++) {
      const sl = CAR.slotWheel[i], h = CAR.hubs[i], left = (i & 1) === 0;
      objPrev(sl).set(objModel(sl));
      const a = -(i < 2 ? steer : 0) + (left ? PI : 0), c = Math.cos(a), sn = Math.sin(a);
      const g = left ? spin[i] : -spin[i], cg = Math.cos(g), sg = Math.sin(g);
      t[0] = c * cg; t[1] = sg; t[2] = -sn * cg; t[3] = 0;
      t[4] = -c * sg; t[5] = cg; t[6] = sn * sg; t[7] = 0;
      t[8] = sn; t[9] = 0; t[10] = c; t[11] = 0;
      t[12] = h[0]; t[13] = h[1] + susp[i]; t[14] = h[2]; t[15] = 1;
      m4mul(objModel(sl), body, t);
    }
  }
};

CARS.register(CAR);
})();
